## 第三方 H5 SDK

第三方 H5 SDK 通常依赖浏览器全局对象，应延迟到客户端加载，不要在通用模块顶层静态引入。

```js
createComponent({
  async ready () {
    const sdk = await import('third-party-h5-sdk')
    sdk.init({})
  }
})
```

如果 SDK 需要容器节点，当前按 `../mpx2rn` 公共部分中的节点访问规则在客户端挂载后获取；未来替换为 mpx base skill。SDK 配置、密钥、回调域名、跨域和 CSP 仍需按 Web 安全要求处理。

### 异步初始化与卸载清理

动态 `import()` 和 SDK 自身初始化都可能在组件卸载后才完成。在每个异步边界后
检查组件是否已卸载；卸载时销毁 SDK 实例、Observer 和事件监听。

```js
createComponent({
  async ready () {
    if (__mpx_mode__ !== 'web' || typeof window === 'undefined') return
    this.sdkDetached = false
    const { default: sdk } = await import('third-party-h5-sdk')
    if (this.sdkDetached) return
    const instance = await sdk.init({})
    if (this.sdkDetached) {
      instance.destroy && instance.destroy()
      return
    }
    this.sdkInstance = instance
  },
  detached () {
    this.sdkDetached = true
    if (this.sdkInstance && this.sdkInstance.destroy) this.sdkInstance.destroy()
    if (this.resizeObserver) this.resizeObserver.disconnect()
  }
})
```

不要只处理顶层静态引入，还要处理快速切页、异步返回晚于卸载和重复进入造成的资源泄漏。

清理要沿资源所有权追踪到底：组件负责销毁它持有的 SDK/图表实例并断开自己创建的 Observer；SDK/helper 若在内部注册 DOM、window、AbortSignal 等事件，应由它返回实例的 `destroy()` 成对移除。调用侧不必重复移除 SDK 私有监听，但必须在正常卸载与异步晚到两条路径都调用该 `destroy()`。验收时同时检查组件文件和 SDK/helper 文件，不能只在组件生命周期方法中搜索 `removeEventListener`。

---

## 文件维度隔离

如果组件主体逻辑依赖浏览器或第三方 H5 SDK，优先使用 Web 文件维度隔离：

```text
components/
└── map-panel.web.mpx  # Web 实现，可安全引入 H5 SDK / Vue 组件 / DOM 逻辑
```

文件维度隔离可以避免 Web-only 依赖进入通用模块，也能让 Web 组件按浏览器语义组织代码。

module.exports = {
  publicPath: '/mall/',
  pluginOptions: {
    mpx: {
      plugin: {
        webConfig: {
          useSSR: true,
          routeConfig: {
            mode: 'history',
            base: '/mall/'
          }
        }
      }
    }
  }
}

import { defineStore } from '@mpxjs/pinia'
import { fetchProduct, fetchRecommendations } from '../services/product'

// Promise 不进入可序列化 state；WeakMap 以每个 Pinia store 实例隔离 SSR 请求。
const pendingLoads = new WeakMap()

export const useProductStore = defineStore('product-platform', {
  state: () => ({
    productId: '',
    product: {},
    recommendations: [],
    loaded: false,
    requestVersion: 0
  }),
  actions: {
    loadProduct (productId, requestContext) {
      const normalizedProductId = String(productId || '')
      if (!normalizedProductId) return Promise.resolve(false)

      if (this.loaded && this.productId === normalizedProductId) {
        return Promise.resolve(true)
      }

      const pendingLoad = pendingLoads.get(this)
      if (
        pendingLoad &&
        pendingLoad.productId === normalizedProductId &&
        pendingLoad.requestVersion === this.requestVersion &&
        this.productId === normalizedProductId
      ) {
        return pendingLoad.promise
      }

      const requestVersion = this.requestVersion + 1
      this.requestVersion = requestVersion
      this.productId = normalizedProductId
      this.loaded = false
      this.product = {}
      this.recommendations = []

      const promise = Promise.all([
        fetchProduct(normalizedProductId, requestContext),
        fetchRecommendations(normalizedProductId, requestContext)
      ]).then(([product, recommendations]) => {
        if (
          this.requestVersion !== requestVersion ||
          this.productId !== normalizedProductId
        ) return false

        this.product = product
        this.recommendations = recommendations
        this.loaded = true
        return true
      }).finally(() => {
        const currentPendingLoad = pendingLoads.get(this)
        if (currentPendingLoad && currentPendingLoad.requestVersion === requestVersion) {
          pendingLoads.delete(this)
        }
      })

      pendingLoads.set(this, {
        productId: normalizedProductId,
        requestVersion,
        promise
      })

      return promise
    }
  }
})

import mpx from '@mpxjs/api-proxy'

function firstHeaderValue (value) {
  const headerValue = Array.isArray(value) ? value[0] : value
  return typeof headerValue === 'string' ? headerValue.split(',')[0].trim() : ''
}

function getServerOrigin (req) {
  const headers = req.headers || {}
  const protocol = req.protocol ||
    firstHeaderValue(headers['x-forwarded-proto']) ||
    (req.socket && req.socket.encrypted ? 'https' : 'http')
  const host = firstHeaderValue(headers['x-forwarded-host']) || firstHeaderValue(headers.host)

  if (!host) {
    throw new Error('Unable to resolve the SSR request origin')
  }

  return `${String(protocol).replace(/:$/, '')}://${host}`
}

function getServerHeaders (req) {
  const sourceHeaders = req.headers || {}
  const headers = {}

  ;['authorization', 'cookie', 'accept-language', 'user-agent'].forEach((name) => {
    const value = sourceHeaders[name]
    if (typeof value === 'string') headers[name] = value
  })

  return headers
}

function requestJson (path, requestContext) {
  const req = requestContext && requestContext.req

  if (req) {
    if (typeof fetch !== 'function') {
      return Promise.reject(new Error('The Node SSR runtime must provide fetch'))
    }

    return fetch(`${getServerOrigin(req)}${path}`, {
      headers: getServerHeaders(req)
    }).then((response) => {
      if (!response.ok) {
        throw new Error(`Product API request failed with status ${response.status}`)
      }
      return response.json()
    })
  }

  return new Promise((resolve, reject) => {
    mpx.request({
      url: path,
      success: ({ data }) => resolve(data),
      fail: reject
    })
  })
}

export function fetchProduct (productId, requestContext) {
  return requestJson(`/api/products/${encodeURIComponent(productId)}`, requestContext)
}

export function fetchRecommendations (productId, requestContext) {
  return requestJson(`/api/products/${encodeURIComponent(productId)}/recommendations`, requestContext)
}
